// csv_parser.c
#include "csv_parser.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct CSVParser {
    char** schema;
    size_t schema_len;
    bool initialized;
    // internal parsing state
} CSVParser;

CSVParser* csv_parser_create(const char** schema, size_t schema_len) {
    CSVParser* parser = calloc(1, sizeof(CSVParser));
    if (!parser) return NULL;

    parser->schema = malloc(schema_len * sizeof(char*));
    for (size_t i = 0; i < schema_len; i++) {
        parser->schema[i] = strdup(schema[i]);
    }
    parser->schema_len = schema_len;
    parser->initialized = true;
    return parser;
}

int csv_parser_feed(CSVParser* parser, const char* chunk, size_t len, bool is_last, char** out_json) {
    if (!parser || !chunk || !out_json) return -1;

    // Parse chunk and generate JSON result
    // In production, this would parse CSV data according to schema
    *out_json = malloc(256);
    snprintf(*out_json, 256, "{\"records\":[], \"error\":null}");

    return is_last ? 1 : 0;  // Return 1 for last chunk
}

void csv_parser_free(CSVParser* parser) {
    if (!parser) return;
    for (size_t i = 0; i < parser->schema_len; i++) {
        free(parser->schema[i]);
    }
    free(parser->schema);
    free(parser);
}
```

```go
// csv_stream.go
package main

// #include "csv_parser.h"
// #include <stdlib.h>
import "C"
import (
    "errors"
    "runtime"
    "sync"
    "unsafe"
)

type StreamHandle struct {
    ptr *C.CSVParser
    mu  sync.RWMutex
}

func StartCSVStream(schema []string) (StreamHandle, error) {
    if len(schema) == 0 {
        return StreamHandle{}, errors.New("schema cannot be empty")
    }

    cSchema := make([]*C.char, len(schema))
    for i, s := range schema {
        cSchema[i] = C.CString(s)
    }
    defer func() {
        for _, cs := range cSchema {
            C.free(unsafe.Pointer(cs))
        }
    }()

    ptr := C.csv_parser_create(&cSchema[0], C.size_t(len(schema)))
    if ptr == nil {
        return StreamHandle{}, errors.New("failed to create parser")
    }

    handle := StreamHandle{ptr: ptr}
    runtime.SetFinalizer(&handle, func(h *StreamHandle) {
        h.mu.Lock()
        defer h.mu.Unlock()
        if h.ptr != nil {
            C.csv_parser_free(h.ptr)
            h.ptr = nil
        }
    })

    return handle, nil
}

func FeedChunk(handle StreamHandle, chunk []byte, isLast bool) (string, error) {
    handle.mu.RLock()
    defer handle.mu.RUnlock()

    if handle.ptr == nil {
        return "", errors.New("invalid stream handle")
    }

    var cChunk *C.char
    if len(chunk) > 0 {
        cChunk = C.CBytes(chunk)
        defer C.free(unsafe.Pointer(cChunk))
    }

    var cJson *C.char
    result := C.csv_parser_feed(
        handle.ptr,
        cChunk,
        C.size_t(len(chunk)),
        C.bool(isLast),
        &cJson,
    )

    if result < 0 {
        return "", errors.New("parsing error")
    }

    jsonStr := C.GoString(cJson)
    C.free(unsafe.Pointer(cJson))

    return jsonStr, nil
}
```

